    ae: ['ARE', 'ADM1'], al: ['ALB', 'ADM2'], at: ['AUT', 'ADM2'], au: ['AUS', 'ADM1'], az: ['AZE', 'ADM2'], bg: ['BGR', 'ADM1'], by: ['BLR', 'ADM1'], ca: ['CAN', 'ADM1'], ch: ['CHE', 'ADM1'], cn: ['CHN', 'ADM1'], cz: ['CZE', 'ADM2'], de: ['DEU', 'ADM3'], dz: ['DZA', 'ADM1'], eg: ['EGY', 'ADM1'], es: ['ESP', 'ADM2'], fr: ['FRA', 'ADM2'], gr: ['GRC', 'ADM3'], hr: ['HRV', 'ADM1'], id: ['IDN', 'ADM1'], ie: ['IRL', 'ADM1'], iq: ['IRQ', 'ADM1'], is: ['ISL', 'ADM1'], it: ['ITA', 'ADM3'], jp: ['JPN', 'ADM1'], ke: ['KEN', 'ADM1'], kg: ['KGZ', 'ADM1'], kh: ['KHM', 'ADM1'], kr: ['KOR', 'ADM1'], kz: ['KAZ', 'ADM1'], la: ['LAO', 'ADM1'], ma: ['MAR', 'ADM2'], md: ['MDA', 'ADM1'], me: ['MNE', 'ADM1'], mk: ['MKD', 'ADM2'], mn: ['MNG', 'ADM1'], mx: ['MEX', 'ADM1'], my: ['MYS', 'ADM1'], no: ['NOR', 'ADM2'], pl: ['POL', 'ADM2'], ps: ['PSE', 'ADM2'], pt: ['PRT', 'ADM2'], ro: ['ROU', 'ADM1'], rs: ['SRB', 'ADM2'], ru: ['RUS', 'ADM1'], si: ['SVN', 'ADM2'], sk: ['SVK', 'ADM2'], th: ['THA', 'ADM1'], tj: ['TJK', 'ADM1'], tr: ['TUR', 'ADM1'], ua: ['UKR', 'ADM1'], uk: ['GBR', 'ADM2'], us: ['USA', 'ADM1'], uz: ['UZB', 'ADM1'], vn: ['VNM', 'ADM1']
